use native_browser::{browser::Browser,headless};
fn main(){let a:Vec<String>=std::env::args().collect(); if a.get(1).map(String::as_str)==Some("--headless"){if a.len()!=5||a[3]!="--output"{eprintln!("usage: native-browser --headless <url-or-path> --output <png>");std::process::exit(2)} if let Err(e)=headless::render(&a[2],&a[4]){eprintln!("{e}");std::process::exit(1)} return} let source=a.get(1).cloned().unwrap_or_else(||"index.html".into()); match Browser::load(&source,native_browser::model::Size{width:800,height:600}){Ok(b)=>println!("loaded {} bytes; desktop frontend ready",b.framebuffer().len()),Err(e)=>eprintln!("load error: {e}")}}
